sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   // 获取申请状态
    var status = g_form.getValue('approval');
	if (status === 'Approved') {
        // 1. 全部字段设为只读
        g_form.setReadOnly('leave_date_start', true);
        g_form.setReadOnly('leave_time_start', true);
        g_form.setReadOnly('leave_date_end', true);
        g_form.setReadOnly('leave_time_end', true);
        g_form.setReadOnly('leave_hour', true);
        g_form.setReadOnly('leave_type', true);
        g_form.setReadOnly('short_description', true);

	}

}
